#!/usr/bin/env python3
# BENCHREFRESH (docs/tasks/2.1.0/43): renders the honest delta table — the new baseline
# vs one or more predecessor result sets — from the JMH result JSONs. BENCHMARKS.md's
# delta sections are GENERATED by this script (never hand-typed), the same discipline
# as render-bench-baseline.py.
#
# Usage: python3 scripts/render-bench-delta.py <label=new.json> <olderLabel=older.json> ...
# The FIRST pair is the new baseline; every following pair is a comparison column.
# A scenario missing from any set renders as "—"; a move >25% gets a flag marker.
import json
import sys


def load(path):
    rows = {}
    for r in json.load(open(path)):
        m = r["benchmark"].split(".")[-1]
        p = r.get("params") or {}
        key = (m, tuple(sorted((k, str(v)) for k, v in p.items())))
        rows[key] = r["primaryMetric"]["score"]
    return rows


def main():
    pairs = []
    for arg in sys.argv[1:]:
        label, path = arg.split("=", 1)
        pairs.append((label, load(path)))
    new_label, new = pairs[0]

    keys = sorted(new.keys(), key=lambda k: (k[0], k[1]))
    header_cols = [label for label, _ in pairs[1:]]

    out = []
    ratio_header = " | ".join(f"{new_label} vs {c}" for c in header_cols)
    out.append("| Scenario | Params | " + " | ".join(header_cols + [new_label + " (new)"]) + " | " + ratio_header + " |")
    out.append("|---|" + "---|" * (2 + len(header_cols) + 1))
    for (m, pt) in keys:
        params = ",".join(f"{k}={v}" for k, v in pt) or "—"
        new_score = new[(m, pt)]
        cells = []
        ratios = []
        for label, old in pairs[1:]:
            old_score = old.get((m, pt))
            if old_score:
                cells.append(f"{old_score:,.0f}")
                ratio = new_score / old_score
                mark = ""
                if ratio <= 0.75:
                    mark = " ⚠️"  # a >25% regression on the new set
                elif ratio >= 1.5:
                    mark = " ↑"    # a >50% improvement
                ratios.append(f"{ratio:.2f}×{mark}")
            else:
                cells.append("—")
                ratios.append("—")
        out.append(f"| `{m}` | {params} | " + " | ".join(cells) + f" | {new_score:,.0f} | " + " | ".join(ratios) + " |")
    print("\n".join(out))


if __name__ == "__main__":
    main()
